<div class="d-flex justify-content-between align-items-center mb-3"><h4>داشبورد مدیریت قیمت</h4><form method="post" action="/pricing/public/queue/rebuild"><input type="hidden" name="_csrf" value="<?=\App\Core\Security::e(\App\Core\Security::csrf())?>"><button class="btn btn-primary">بازسازی صف</button></form></div><div class="row g-3"><?php foreach(['products'=>'کل محصولات','without_price'=>'بدون قیمت','expired'=>'منقضی','queue'=>'در صف','critical'=>'بحرانی','suppliers'=>'تأمین‌کنندگان','incomplete_sources'=>'منابع ناقص','high_spread'=>'اختلاف بالای ۲۰٪','in_progress'=>'در حال بررسی','completed'=>'تکمیل‌شده','workflow_active'=>'Workflow فعال','unread_notifications'=>'اعلان خوانده‌نشده'] as $k=>$label):?><div class="col-6 col-md-3 col-xl-2"><div class="card h-100"><div class="card-body"><div class="text-muted small"><?=$label?></div><div class="fs-4 fw-bold"><?=number_format((int)$stats[$k])?></div></div></div></div><?php endforeach;?></div><div class="card mt-4"><div class="card-header">نمودار روند دریافت قیمت</div><div class="card-body"><?php $maxTrend=$trend ? max(array_map(fn($x)=>(int)$x['received'],$trend)) : 1; foreach($trend as $t):?><div class="mb-3"><div class="d-flex justify-content-between"><span><?=\App\Core\Security::e($t['month_name'])?></span><span><?=number_format((int)$t['received'])?></span></div><div class="progress" role="progressbar" aria-label="روند دریافت"><div class="progress-bar" style="width:<?=round(((int)$t['received']/$maxTrend)*100)?>%"></div></div><small class="text-muted">میانگین قیمت: <?=number_format((float)$t['avg_price'],2)?></small></div><?php endforeach;?></div></div>